package com.example.bikerental; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="bike_reviews") public class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Bike bike; @Column(nullable=false) private String username; @Column(nullable=false) private String customerName; @Column(nullable=false) private int rating; @Column(length=1000) private String comment; private LocalDateTime createdAt=LocalDateTime.now(); public Review(){} public Review(Bike b,String u,String n,int r,String c){bike=b;username=u;customerName=n;rating=r;comment=c;} public Long getId(){return id;} public Bike getBike(){return bike;} public String getUsername(){return username;} public String getCustomerName(){return customerName;} public int getRating(){return rating;} public String getComment(){return comment;} public LocalDateTime getCreatedAt(){return createdAt;} }